import * as React from "react";

export type MonitorIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function MonitorIcon({ size = 20, ...props }: MonitorIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="4.5" width="16" height="11" rx="1" /><path d="M9 19.5 L15 19.5 M12 15.5 L12 19.5 M6 19.5 L18 19.5" />
    </svg>
  );
}
